<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\{EWallet,FeeSetting,Order,User,WalletTransaction}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class SuperAdminController extends Controller { public function ledger(){return response()->json(['wallet_balances'=>EWallet::sum('balance'),'wallet_count'=>EWallet::count(),'transactions'=>WalletTransaction::with('wallet.user:id,name')->latest()->paginate(50)]);} public function fees(){return response()->json(FeeSetting::orderBy('key')->get());} public function updateFee(Request $r,FeeSetting $feeSetting){$d=$r->validate(['amount'=>'required|integer|min:0','description'=>'nullable|string|max:255']);$feeSetting->update($d);return response()->json(['fee'=>$feeSetting->fresh()]);} public function monitoring(){return response()->json(['users'=>User::count(),'active_orders'=>Order::where('status','!=','COMPLETED')->count(),'orders_by_status'=>Order::select('status',DB::raw('count(*) as total'))->groupBy('status')->pluck('total','status'),'wallet_balance'=>EWallet::sum('balance'),'open_disputes'=>DB::table('disputes')->where('status','OPEN')->count()]);} }
